package com.servletspy;

import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;

/**
 * ExamResultServlet - Processes student exam result data
 * Demonstrates:
 * - Servlet lifecycle (init, service, destroy)
 * - Request processing (reading form parameters)
 * - Validation (checking empty, numeric, range)
 * - Business logic (calculating total, percentage, result status)
 * - RequestDispatcher (forwarding to JSP)
 * - sendRedirect (redirecting on validation failure)
 */
@WebServlet("/exam-result")
public class ExamResultServlet extends HttpServlet {

    /**
     * Servlet lifecycle: Initialization
     * Called once when the servlet is first loaded
     */
    @Override
    public void init() {
        System.out.println("=== ExamResultServlet Initialized ===");
        System.out.println("Servlet Name: " + getServletName());
        System.out.println("Servlet Context: " + getServletContext().getServletContextName());
    }

    /**
     * Handles POST requests from the exam result form
     */
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        System.out.println("\n--- ExamResultServlet: Processing POST request ---");

        // Read form parameters
        String studentName = req.getParameter("studentName");
        String rollNumber = req.getParameter("rollNumber");
        String subject1Str = req.getParameter("subject1");
        String subject2Str = req.getParameter("subject2");
        String subject3Str = req.getParameter("subject3");

        System.out.println("Form Data Received:");
        System.out.println("  Student Name: " + studentName);
        System.out.println("  Roll Number: " + rollNumber);
        System.out.println("  Subject 1: " + subject1Str);
        System.out.println("  Subject 2: " + subject2Str);
        System.out.println("  Subject 3: " + subject3Str);

        // Initialize variables
        boolean isValid = true;
        StringBuilder errorMessage = new StringBuilder();
        int subject1 = 0, subject2 = 0, subject3 = 0;

        // Validation: Student Name
        if (studentName == null || studentName.isBlank()) {
            isValid = false;
            errorMessage.append("• Student Name cannot be empty<br>");
            System.out.println("Validation Error: Student Name is empty");
        }

        // Validation: Roll Number
        if (rollNumber == null || rollNumber.isBlank()) {
            isValid = false;
            errorMessage.append("• Roll Number cannot be empty<br>");
            System.out.println("Validation Error: Roll Number is empty");
        }

        // Validation: Subject 1 Marks
        try {
            subject1 = Integer.parseInt(subject1Str);
            if (subject1 < 0 || subject1 > 100) {
                isValid = false;
                errorMessage.append("• Subject 1 Marks must be between 0 and 100<br>");
                System.out.println("Validation Error: Subject 1 out of range: " + subject1);
            }
        } catch (NumberFormatException e) {
            isValid = false;
            errorMessage.append("• Subject 1 Marks must be numeric<br>");
            System.out.println("Validation Error: Subject 1 not numeric");
        }

        // Validation: Subject 2 Marks
        try {
            subject2 = Integer.parseInt(subject2Str);
            if (subject2 < 0 || subject2 > 100) {
                isValid = false;
                errorMessage.append("• Subject 2 Marks must be between 0 and 100<br>");
                System.out.println("Validation Error: Subject 2 out of range: " + subject2);
            }
        } catch (NumberFormatException e) {
            isValid = false;
            errorMessage.append("• Subject 2 Marks must be numeric<br>");
            System.out.println("Validation Error: Subject 2 not numeric");
        }

        // Validation: Subject 3 Marks
        try {
            subject3 = Integer.parseInt(subject3Str);
            if (subject3 < 0 || subject3 > 100) {
                isValid = false;
                errorMessage.append("• Subject 3 Marks must be between 0 and 100<br>");
                System.out.println("Validation Error: Subject 3 out of range: " + subject3);
            }
        } catch (NumberFormatException e) {
            isValid = false;
            errorMessage.append("• Subject 3 Marks must be numeric<br>");
            System.out.println("Validation Error: Subject 3 not numeric");
        }

        if (isValid) {
            System.out.println("✓ All validations PASSED");

            // Business Logic: Calculate results
            int totalMarks = subject1 + subject2 + subject3;
            double percentage = (totalMarks / 300.0) * 100; // 300 is max total (100+100+100)
            String resultStatus = calculateResultStatus(percentage);

            System.out.println("Calculations:");
            System.out.println("  Total Marks: " + totalMarks);
            System.out.println("  Percentage: " + String.format("%.2f", percentage) + "%");
            System.out.println("  Result Status: " + resultStatus);

            // Set request attributes for JSP
            req.setAttribute("studentName", studentName);
            req.setAttribute("rollNumber", rollNumber);
            req.setAttribute("subject1", subject1);
            req.setAttribute("subject2", subject2);
            req.setAttribute("subject3", subject3);
            req.setAttribute("totalMarks", totalMarks);
            req.setAttribute("percentage", percentage);
            req.setAttribute("resultStatus", resultStatus);

            System.out.println("Forwarding to preview page: /exam_result_preview.jsp");

            // Forward to result preview page (preserves request attributes)
            req.getRequestDispatcher("/exam_result_preview.jsp").forward(req, resp);

        } else {
            System.out.println("✗ Validation FAILED");

            // Preserve form data for user correction
            req.setAttribute("error", errorMessage.toString());
            req.setAttribute("studentName", studentName);
            req.setAttribute("rollNumber", rollNumber);
            req.setAttribute("subject1", subject1Str);
            req.setAttribute("subject2", subject2Str);
            req.setAttribute("subject3", subject3Str);

            System.out.println("Forwarding back to form with error message");

            // Forward back to form with error and preserved data
            req.getRequestDispatcher("/exam_result_form.jsp").forward(req, resp);
        }
    }

    /**
     * Calculate result status based on percentage
     * Distinction: >= 75%
     * First Class: 60% to < 75%
     * Pass: 40% to < 60%
     * Fail: < 40%
     */
    private String calculateResultStatus(double percentage) {
        if (percentage >= 75) {
            return "Distinction ";
        } else if (percentage >= 60) {
            return "First Class ";
        } else if (percentage >= 40) {
            return "Pass ✓";
        } else {
            return "Fail ✗";
        }
    }

    /**
     * Servlet lifecycle: Destruction
     * Called when the servlet is unloaded (server restart, redeployment)
     */
    @Override
    public void destroy() {
        System.out.println("=== ExamResultServlet Destroyed ===");
    }
}
